import { test, expect } from '@playwright/test';

test.describe('Bottom Sheet Replacement for Dropdowns on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com');
    await page.setViewportSize({ width: 375, height: 812 }); // Mobile viewport
  });

  test('should display bottom sheet when dropdown is clicked', async ({ page }) => {
    await page.getByRole('button', { name: 'Open Dropdown' }).click();
    const bottomSheet = page.getByRole('dialog', { name: 'Bottom Sheet' });
    await expect(bottomSheet).toBeVisible();
  });

  test('should allow selection from bottom sheet', async ({ page }) => {
    await page.getByRole('button', { name: 'Open Dropdown' }).click();
    const bottomSheet = page.getByRole('dialog', { name: 'Bottom Sheet' });
    await expect(bottomSheet).toBeVisible();

    await bottomSheet.getByText('Option 1').click();
    const selectedValue = page.getByLabel('Selected Value');
    await expect(selectedValue).toHaveText('Option 1');
  });
});
